  1→import { create } from 'zustand';
  2→import type { FolderChild } from '@cipherbox/crypto';
  3→
  4→/**
  5→ * A folder node in the in-memory folder tree.
  6→ * Contains decrypted folder data and navigation state.
  7→ */
  8→export type FolderNode = {
  9→  /** UUID for internal reference (null string 'root' for root folder) */
 10→  id: string;
 11→  /** Folder name */
 12→  name: string;
 13→  /** IPNS name for this folder (k51.../bafzaa... format) */
 14→  ipnsName: string;
 15→  /** Parent folder ID (null for root) */
 16→  parentId: string | null;
 17→  /** Decrypted children (files and subfolders) */
 18→  children: FolderChild[];
 19→  /** Has metadata been fetched and decrypted? */
 20→  isLoaded: boolean;
 21→  /** Is metadata currently being fetched? */
 22→  isLoading: boolean;
 23→  /** Current IPNS sequence number */
 24→  sequenceNumber: bigint;
 25→  /** Decrypted AES-256 folder key */
 26→  folderKey: Uint8Array;
 27→  /** Decrypted Ed25519 IPNS private key */
 28→  ipnsPrivateKey: Uint8Array;
 29→};
 30→
 31→/**
 32→ * Breadcrumb entry for navigation.
 33→ */
 34→type Breadcrumb = {
 35→  id: string;
 36→  name: string;
 37→};
 38→
 39→type FolderState = {
 40→  // Folder tree indexed by id
 41→  folders: Record<string, FolderNode>;
 42→
 43→  // Current navigation
 44→  currentFolderId: string | null; // null = root
 45→  breadcrumbs: Breadcrumb[];
 46→
 47→  // Publishing state
 48→  pendingPublishes: Set<string>; // folder IDs with pending IPNS publishes
 49→
 50→  // Actions
 51→  setFolder: (folder: FolderNode) => void;
 52→  updateFolderChildren: (folderId: string, children: FolderChild[]) => void;
 53→  updateFolderSequence: (folderId: string, sequenceNumber: bigint) => void;
 54→  setCurrentFolder: (folderId: string | null) => void;
 55→  setBreadcrumbs: (breadcrumbs: Breadcrumb[]) => void;
 56→  addPendingPublish: (folderId: string) => void;
 57→  removePendingPublish: (folderId: string) => void;
 58→  removeFolder: (folderId: string) => void;
 59→  updateFolderName: (folderId: string, newName: string) => void;
 60→  clearFolders: () => void;
 61→};
 62→
 63→/**
 64→ * Folder store for managing folder tree state.
 65→ *
 66→ * Maintains the in-memory representation of the folder hierarchy
 67→ * with decrypted folder keys and metadata.
 68→ *
 69→ * SECURITY: All folder keys are memory-only - never persisted to storage.
 70→ * Call clearFolders() on logout to zero-fill all key material.
 71→ */
 72→export const useFolderStore = create<FolderState>((set, get) => ({
 73→  // State
 74→  folders: {},
 75→  currentFolderId: null,
 76→  breadcrumbs: [],
 77→  pendingPublishes: new Set<string>(),
 78→
 79→  // Actions
 80→  setFolder: (folder) =>
 81→    set((state) => ({
 82→      folders: { ...state.folders, [folder.id]: folder },
 83→    })),
 84→
 85→  updateFolderChildren: (folderId, children) =>
 86→    set((state) => {
 87→      const folder = state.folders[folderId];
 88→      if (!folder) return state;
 89→
 90→      return {
 91→        folders: {
 92→          ...state.folders,
 93→          [folderId]: { ...folder, children, isLoaded: true, isLoading: false },
 94→        },
 95→      };
 96→    }),
 97→
 98→  updateFolderSequence: (folderId, sequenceNumber) =>
 99→    set((state) => {
100→      const folder = state.folders[folderId];
101→      if (!folder) return state;
102→
103→      return {
104→        folders: {
105→          ...state.folders,
106→          [folderId]: { ...folder, sequenceNumber },
107→        },
108→      };
109→    }),
110→
111→  setCurrentFolder: (folderId) => set({ currentFolderId: folderId }),
112→
113→  setBreadcrumbs: (breadcrumbs) => set({ breadcrumbs }),
114→
115→  addPendingPublish: (folderId) =>
116→    set((state) => {
117→      const newPending = new Set(state.pendingPublishes);
118→      newPending.add(folderId);
119→      return { pendingPublishes: newPending };
120→    }),
121→
122→  removePendingPublish: (folderId) =>
123→    set((state) => {
124→      const newPending = new Set(state.pendingPublishes);
125→      newPending.delete(folderId);
126→      return { pendingPublishes: newPending };
127→    }),
128→
129→  // Remove a folder from local state (after deletion)
130→  // Also clears the folder's key material from memory
131→  removeFolder: (folderId) =>
132→    set((state) => {
133→      const folder = state.folders[folderId];
134→      if (!folder) return state;
135→
136→      // Zero-fill keys before removing
137→      if (folder.folderKey) folder.folderKey.fill(0);
138→      if (folder.ipnsPrivateKey) folder.ipnsPrivateKey.fill(0);
139→
140→      const { [folderId]: _removed, ...remainingFolders } = state.folders;
141→      void _removed; // Intentionally destructured to remove from object
142→      return { folders: remainingFolders };
143→    }),
144→
145→  // Update a folder's name in local state
146→  updateFolderName: (folderId, newName) =>
147→    set((state) => {
148→      const folder = state.folders[folderId];
149→      if (!folder) return state;
150→
151→      return {
152→        folders: {
153→          ...state.folders,
154→          [folderId]: { ...folder, name: newName },
155→        },
156→      };
157→    }),
158→
159→  // [SECURITY: MEDIUM-02] Zero-fill sensitive key material before clearing
160→  clearFolders: () => {
161→    const state = get();
162→
163→    // Best-effort memory clearing - overwrite all folder keys with zeros
164→    for (const folder of Object.values(state.folders)) {
165→      if (folder.folderKey) {
166→        folder.folderKey.fill(0);
167→      }
168→      if (folder.ipnsPrivateKey) {
169→        folder.ipnsPrivateKey.fill(0);
170→      }
171→    }
172→
173→    set({
174→      folders: {},
175→      currentFolderId: null,
176→      breadcrumbs: [],
177→      pendingPublishes: new Set<string>(),
178→    });
179→  },
180→}));
181→
182→// Expose store on window for E2E testing (development only)
183→if (typeof window !== 'undefined' && import.meta.env.DEV) {
184→  // eslint-disable-next-line @typescript-eslint/no-explicit-any
185→  (window as any).__ZUSTAND_FOLDER_STORE__ = useFolderStore;
186→}
187→

  1→/**
  2→ * Device Identity Persistence
  3→ *
  4→ * Manages the device's Ed25519 keypair in IndexedDB. This keypair is unique
  5→ * per physical device/browser and cannot be re-derived (unlike the user's
  6→ * vault key which comes from Web3Auth).
  7→ *
  8→ * If IndexedDB is unavailable (incognito, etc.) or the stored keypair is
  9→ * cleared by the browser, a new keypair is generated. This creates a new
 10→ * device entry in the registry (the old one becomes orphaned).
 11→ */
 12→
 13→import { generateDeviceKeypair, deriveDeviceId, type DeviceKeypair } from '@cipherbox/crypto';
 14→
 15→const DB_NAME = 'cipherbox-device';
 16→const DB_VERSION = 1;
 17→const STORE_NAME = 'keys';
 18→const KEYPAIR_KEY = 'device-ed25519';
 19→
 20→/**
 21→ * Open the IndexedDB database, creating the object store on upgrade.
 22→ */
 23→function openDB(): Promise<IDBDatabase> {
 24→  return new Promise((resolve, reject) => {
 25→    const request = indexedDB.open(DB_NAME, DB_VERSION);
 26→    request.onupgradeneeded = () => {
 27→      request.result.createObjectStore(STORE_NAME);
 28→    };
 29→    request.onsuccess = () => resolve(request.result);
 30→    request.onerror = () => reject(request.error);
 31→  });
 32→}
 33→
 34→/**
 35→ * Load device keypair from IndexedDB.
 36→ *
 37→ * Stores keys as plain number arrays because Uint8Array doesn't
 38→ * serialize reliably across all browsers in IndexedDB.
 39→ *
 40→ * @returns Keypair if found, null if not found or IndexedDB unavailable
 41→ */
 42→async function loadDeviceKeypair(): Promise<{
 43→  publicKey: Uint8Array;
 44→  privateKey: Uint8Array;
 45→} | null> {
 46→  try {
 47→    const db = await openDB();
 48→    const tx = db.transaction(STORE_NAME, 'readonly');
 49→    const store = tx.objectStore(STORE_NAME);
 50→
 51→    return new Promise((resolve, reject) => {
 52→      const request = store.get(KEYPAIR_KEY);
 53→      request.onsuccess = () => {
 54→        const val = request.result;
 55→        if (val && val.publicKey && val.privateKey) {
 56→          resolve({
 57→            publicKey: new Uint8Array(val.publicKey),
 58→            privateKey: new Uint8Array(val.privateKey),
 59→          });
 60→        } else {
 61→          resolve(null);
 62→        }
 63→      };
 64→      request.onerror = () => reject(request.error);
 65→    });
 66→  } catch {
 67→    // IndexedDB unavailable (incognito, etc.)
 68→    return null;
 69→  }
 70→}
 71→
 72→/**
 73→ * Save device keypair to IndexedDB.
 74→ *
 75→ * Converts Uint8Array to plain number arrays before storing
 76→ * to avoid serialization issues across browsers.
 77→ */
 78→async function saveDeviceKeypair(keypair: {
 79→  publicKey: Uint8Array;
 80→  privateKey: Uint8Array;
 81→}): Promise<void> {
 82→  const db = await openDB();
 83→  const tx = db.transaction(STORE_NAME, 'readwrite');
 84→  const store = tx.objectStore(STORE_NAME);
 85→
 86→  store.put(
 87→    {
 88→      publicKey: Array.from(keypair.publicKey),
 89→      privateKey: Array.from(keypair.privateKey),
 90→    },
 91→    KEYPAIR_KEY
 92→  );
 93→
 94→  return new Promise((resolve, reject) => {
 95→    tx.oncomplete = () => resolve();
 96→    tx.onerror = () => reject(tx.error);
 97→  });
 98→}
 99→
100→/**
101→ * Get or create the device's Ed25519 identity.
102→ *
103→ * Tries to load an existing keypair from IndexedDB first.
104→ * If not found, generates a new one and persists it.
105→ *
106→ * The returned DeviceKeypair includes:
107→ * - publicKey: 32-byte Ed25519 public key
108→ * - privateKey: 32-byte Ed25519 private key (seed)
109→ * - deviceId: SHA-256 hex of the public key
110→ *
111→ * @returns Device keypair with derived device ID
112→ */
113→export async function getOrCreateDeviceIdentity(): Promise<DeviceKeypair> {
114→  // Try loading existing keypair from IndexedDB
115→  const stored = await loadDeviceKeypair();
116→  if (stored) {
117→    const deviceId = deriveDeviceId(stored.publicKey);
118→    return {
119→      publicKey: stored.publicKey,
120→      privateKey: stored.privateKey,
121→      deviceId,
122→    };
123→  }
124→
125→  // Generate new keypair and persist
126→  const keypair = generateDeviceKeypair();
127→  await saveDeviceKeypair({
128→    publicKey: keypair.publicKey,
129→    privateKey: keypair.privateKey,
130→  });
131→
132→  return keypair;
133→}
134→

 1→/**
 2→ * Services barrel export
 3→ *
 4→ * Re-exports all service modules for cleaner imports.
 5→ */
 6→
 7→export * from './delete.service';
 8→export * from './download.service';
 9→export * from './file-crypto.service';
10→export * from './file-metadata.service';
11→export * from './streaming-crypto.service';
12→export * from './folder.service';
13→export * from './ipns.service';
14→export * from './upload.service';
15→

 1→/**
 2→ * @cipherbox/crypto - Folder Metadata Types
 3→ *
 4→ * Type definitions for encrypted folder metadata stored in IPNS records.
 5→ * v2 schema with per-file IPNS pointers (FilePointer children).
 6→ */
 7→
 8→import type { FilePointer } from '../file/types';
 9→
10→/**
11→ * Decrypted folder metadata structure (v2).
12→ * The entire FolderMetadata object is encrypted as a single blob with AES-256-GCM.
13→ * Children are FolderEntry (subfolders) or FilePointer (slim IPNS references).
14→ */
15→export type FolderMetadata = {
16→  /** Schema version */
17→  version: 'v2';
18→  /** Folders and file pointers in this folder */
19→  children: FolderChild[];
20→};
21→
22→/**
23→ * A child entry can be either a folder or a file pointer.
24→ */
25→export type FolderChild = FolderEntry | FilePointer;
26→
27→/**
28→ * Subfolder entry within folder metadata.
29→ * Contains ECIES-wrapped keys for accessing the subfolder.
30→ */
31→export type FolderEntry = {
32→  type: 'folder';
33→  /** UUID for internal reference */
34→  id: string;
35→  /** Folder name (plaintext, since whole metadata is encrypted) */
36→  name: string;
37→  /** IPNS name for this subfolder (k51... format) */
38→  ipnsName: string;
39→  /** Hex-encoded ECIES-wrapped Ed25519 private key for IPNS signing */
40→  ipnsPrivateKeyEncrypted: string;
41→  /** Hex-encoded ECIES-wrapped AES-256 key for decrypting subfolder metadata */
42→  folderKeyEncrypted: string;
43→  /** Creation timestamp (Unix ms) */
44→  createdAt: number;
45→  /** Last modification timestamp (Unix ms) */
46→  modifiedAt: number;
47→};
48→
49→/**
50→ * Encrypted folder metadata for storage/transmission.
51→ * This is what gets uploaded to IPFS and referenced by IPNS.
52→ */
53→export type EncryptedFolderMetadata = {
54→  /** Hex-encoded 12-byte IV for AES-GCM */
55→  iv: string;
56→  /** Base64-encoded AES-GCM ciphertext (includes 16-byte auth tag) */
57→  data: string;
58→};
59→

 1→/**
 2→ * @cipherbox/crypto - Per-File Metadata Types
 3→ *
 4→ * Type definitions for per-file IPNS metadata records.
 5→ * Each file gets its own IPNS record containing encrypted metadata,
 6→ * while the parent folder only stores a slim FilePointer reference.
 7→ */
 8→
 9→/** A single past version of a file. Stores full crypto context for independent decryption. */
10→export type VersionEntry = {
11→  /** IPFS CID of the encrypted file content for this version */
12→  cid: string;
13→  /** Hex-encoded ECIES-wrapped AES-256 key for decrypting this version */
14→  fileKeyEncrypted: string;
15→  /** Hex-encoded IV used for this version's encryption */
16→  fileIv: string;
17→  /** Original file size in bytes (before encryption) */
18→  size: number;
19→  /** When this version was created (Unix ms) -- i.e., when it became a "past" version */
20→  timestamp: number;
21→  /** Encryption mode used for this version */
22→  encryptionMode: 'GCM' | 'CTR';
23→};
24→
25→/**
26→ * Decrypted per-file metadata structure.
27→ * Stored as an encrypted blob in the file's own IPNS record.
28→ * Encrypted with the parent folder's folderKey (NOT the file's own key).
29→ */
30→export type FileMetadata = {
31→  /** Schema version */
32→  version: 'v1';
33→  /** IPFS CID of the encrypted file content */
34→  cid: string;
35→  /** Hex-encoded ECIES-wrapped AES-256 key for decrypting file */
36→  fileKeyEncrypted: string;
37→  /** Hex-encoded IV used for file encryption */
38→  fileIv: string;
39→  /** Original file size in bytes (before encryption) */
40→  size: number;
41→  /** MIME type of the original file */
42→  mimeType: string;
43→  /** Encryption mode (optional for backward compat; defaults to 'GCM') */
44→  encryptionMode?: 'GCM' | 'CTR';
45→  /** Creation timestamp (Unix ms) */
46→  createdAt: number;
47→  /** Last modification timestamp (Unix ms) */
48→  modifiedAt: number;
49→  /** Past versions of this file (newest first). Omitted if no versions exist. */
50→  versions?: VersionEntry[];
51→};
52→
53→/**
54→ * Slim file reference stored in v2 folder metadata.
55→ * Points to a file's own IPNS record instead of embedding all file data inline.
56→ */
57→export type FilePointer = {
58→  type: 'file';
59→  /** UUID for internal reference */
60→  id: string;
61→  /** File name (plaintext, since folder metadata is encrypted) */
62→  name: string;
63→  /** IPNS name of the file's own metadata record */
64→  fileMetaIpnsName: string;
65→  /** Hex-encoded ECIES-wrapped Ed25519 private key for signing this file's IPNS record.
66→   *  Present for files created after the random-key migration. Absent for legacy files
67→   *  whose IPNS key is derived deterministically via HKDF. */
68→  ipnsPrivateKeyEncrypted?: string;
69→  /** Creation timestamp (Unix ms) */
70→  createdAt: number;
71→  /** Last modification timestamp (Unix ms) */
72→  modifiedAt: number;
73→};
74→
75→/**
76→ * Encrypted file metadata for storage/transmission.
77→ * Same format as EncryptedFolderMetadata (hex IV + base64 ciphertext).
78→ */
79→export type EncryptedFileMetadata = {
80→  /** Hex-encoded 12-byte IV for AES-GCM */
81→  iv: string;
82→  /** Base64-encoded AES-GCM ciphertext (includes 16-byte auth tag) */
83→  data: string;
84→};
