  1→/**
  2→ * Search Index Service
  3→ *
  4→ * Manages a client-side search index for file and folder names using MiniSearch.
  5→ * The index is encrypted with AES-256-GCM (key derived via HKDF from the user's
  6→ * vault private key) before persisting to IndexedDB for zero-knowledge on-disk storage.
  7→ *
  8→ * This is a pure TypeScript service with no React dependencies.
  9→ */
 10→
 11→import MiniSearch from 'minisearch';
 12→import type { FolderNode } from '../stores/folder.store';
 13→
 14→// ---------------------------------------------------------------------------
 15→// Types
 16→// ---------------------------------------------------------------------------
 17→
 18→/** A document stored in the MiniSearch index. */
 19→type SearchDocument = {
 20→  /** Unique key: `${folderId}:${childId}` (avoids collisions across folders) */
 21→  id: string;
 22→  /** File or folder name (what users search for) */
 23→  name: string;
 24→  /** Whether this is a file or folder */
 25→  type: 'file' | 'folder';
 26→  /** Breadcrumb path like "My Vault / Documents / Reports" */
 27→  parentPath: string;
 28→  /** Folder ID for navigation on result click */
 29→  parentFolderId: string;
 30→  /** Timestamp for display in results (Unix ms) */
 31→  modifiedAt: number;
 32→};
 33→
 34→/** A search result returned by the service. */
 35→export type SearchResult = {
 36→  id: string;
 37→  name: string;
 38→  type: 'file' | 'folder';
 39→  parentPath: string;
 40→  parentFolderId: string;
 41→  modifiedAt: number;
 42→  /** MiniSearch relevance score (higher = better match) */
 43→  score: number;
 44→  /** Match info from MiniSearch, maps field name to matching terms */
 45→  match: Record<string, string[]>;
 46→};
 47→
 48→// ---------------------------------------------------------------------------
 49→// MiniSearch options (shared between constructor and loadJSON)
 50→// ---------------------------------------------------------------------------
 51→
 52→const MINISEARCH_OPTIONS = {
 53→  fields: ['name'] as const,
 54→  storeFields: [
 55→    'name',
 56→    'type',
 57→    'parentPath',
 58→    'parentFolderId',
 59→    'modifiedAt',
 60→  ] as const,
 61→  searchOptions: {
 62→    fuzzy: 0.2,
 63→    prefix: true,
 64→    boost: { name: 1 },
 65→  },
 66→};
 67→
 68→// ---------------------------------------------------------------------------
 69→// IndexedDB constants
 70→// ---------------------------------------------------------------------------
 71→
 72→const IDB_NAME = 'cipherbox-search';
 73→const IDB_VERSION = 1;
 74→const IDB_STORE = 'index';
 75→const IDB_KEY = 'encrypted-index';
 76→
 77→// ---------------------------------------------------------------------------
 78→// HKDF constants
 79→// ---------------------------------------------------------------------------
 80→
 81→const HKDF_INFO = 'cipherbox-search-index-v1';
 82→
 83→// ---------------------------------------------------------------------------
 84→// IndexedDB helpers (follows pattern from device/identity.ts)
 85→// ---------------------------------------------------------------------------
 86→
 87→function openSearchDB(): Promise<IDBDatabase> {
 88→  return new Promise((resolve, reject) => {
 89→    const request = indexedDB.open(IDB_NAME, IDB_VERSION);
 90→    request.onupgradeneeded = () => {
 91→      request.result.createObjectStore(IDB_STORE);
 92→    };
 93→    request.onsuccess = () => resolve(request.result);
 94→    request.onerror = () => reject(request.error);
 95→  });
 96→}
 97→
 98→// ---------------------------------------------------------------------------
 99→// SearchIndexService
100→// ---------------------------------------------------------------------------
101→
102→export class SearchIndexService {
103→  private miniSearch: MiniSearch<SearchDocument>;
104→  private indexVersion: number = 0;
105→
106→  constructor() {
107→    this.miniSearch = new MiniSearch<SearchDocument>(MINISEARCH_OPTIONS);
108→  }
109→
110→  /**
111→   * Build the full index from the folder store's folder tree.
112→   * Walks all loaded FolderNodes and indexes their children (files and folders).
113→   *
114→   * @param folders - Record<string, FolderNode> from folder store
115→   */
116→  buildFromFolderTree(folders: Record<string, FolderNode>): void {
117→    this.miniSearch.removeAll();
118→
119→    const documents: SearchDocument[] = [];
120→
121→    for (const folder of Object.values(folders)) {
122→      const parentPath = this.buildPath(folder.id, folders);
123→
124→      // Index each child (files and subfolders)
125→      for (const child of folder.children) {
126→        documents.push({
127→          id: `${folder.id}:${child.id}`,
128→          name: child.name,
129→          type: child.type === 'folder' ? 'folder' : 'file',
130→          parentPath,
131→          parentFolderId: folder.id,
132→          modifiedAt: child.modifiedAt ?? child.createdAt ?? 0,
133→        });
134→      }
135→    }
136→
137→    // Also index folders themselves (except root) as searchable items.
138→    // A folder's parent is its parentId, so it appears in search under
139→    // the parent folder's path.
140→    for (const folder of Object.values(folders)) {
141→      if (!folder.parentId) continue; // skip root
142→      const parentFolder = folders[folder.parentId];
143→      if (!parentFolder) continue;
144→
145→      const parentPath = this.buildPath(folder.parentId, folders);
146→
147→      // Use the folder's own id with a "self:" prefix to avoid collision
148→      // with the same folder appearing as a child entry
149→      documents.push({
150→        id: `${folder.parentId}:${folder.id}`,
151→        name: folder.name,
152→        type: 'folder',
153→        parentPath,
154→        parentFolderId: folder.parentId,
155→        modifiedAt: 0, // folders don't have a top-level modifiedAt
156→      });
157→    }
158→
159→    // Deduplicate: children already include subfolder entries from parent.
160→    // The folder-self entries above may overlap with child entries.
161→    // Use a Map to keep only one document per id.
162→    const deduped = new Map<string, SearchDocument>();
163→    for (const doc of documents) {
164→      deduped.set(doc.id, doc);
165→    }
166→
167→    this.miniSearch.addAll(Array.from(deduped.values()));
168→    this.indexVersion++;
169→  }
170→
171→  /**
172→   * Search the index with fuzzy matching.
173→   *
174→   * @param query - user's search string
175→   * @returns Array of SearchResult sorted by relevance score (descending)
176→   */
177→  search(query: string): SearchResult[] {
178→    if (!query.trim()) return [];
179→
180→    const results = this.miniSearch.search(query);
181→
182→    return results.map((result) => ({
183→      id: result.id as string,
184→      name: result.name as string,
185→      type: result.type as 'file' | 'folder',
186→      parentPath: result.parentPath as string,
187→      parentFolderId: result.parentFolderId as string,
188→      modifiedAt: result.modifiedAt as number,
189→      score: result.score,
190→      match: result.match,
191→    }));
192→  }
193→
194→  /**
195→   * Persist the current index to IndexedDB, encrypted with a key derived
196→   * from the user's vault private key via HKDF.
197→   *
198→   * @param userPrivateKey - user's secp256k1 private key (32 bytes) for HKDF derivation
199→   */
200→  async persistEncrypted(userPrivateKey: Uint8Array): Promise<void> {
201→    try {
202→      const searchKey = await this.deriveSearchKey(userPrivateKey);
203→      const serialized = JSON.stringify(this.miniSearch.toJSON());
204→      const plaintext = new TextEncoder().encode(serialized);
205→
206→      const iv = crypto.getRandomValues(new Uint8Array(12));
207→      const ciphertext = await crypto.subtle.encrypt(
208→        { name: 'AES-GCM', iv },
209→        searchKey,
210→        plaintext
211→      );
212→
213→      const db = await openSearchDB();
214→      const tx = db.transaction(IDB_STORE, 'readwrite');
215→      const store = tx.objectStore(IDB_STORE);
216→
217→      // Store as number[] for cross-browser IndexedDB compatibility
218→      store.put(
219→        {
220→          iv: Array.from(iv),
221→          data: Array.from(new Uint8Array(ciphertext)),
222→        },
223→        IDB_KEY
224→      );
225→
226→      await new Promise<void>((resolve, reject) => {
227→        tx.oncomplete = () => resolve();
228→        tx.onerror = () => reject(tx.error);
229→      });
230→    } catch (err) {
231→      console.warn('[SearchIndex] Failed to persist encrypted index:', err);
232→    }
233→  }
234→
235→  /**
236→   * Load the index from IndexedDB and decrypt.
237→   *
238→   * @param userPrivateKey - user's secp256k1 private key (32 bytes) for HKDF derivation
239→   * @returns true if index was loaded successfully, false if not found or decryption failed
240→   */
241→  async loadEncrypted(userPrivateKey: Uint8Array): Promise<boolean> {
242→    try {
243→      const db = await openSearchDB();
244→      const tx = db.transaction(IDB_STORE, 'readonly');
245→      const store = tx.objectStore(IDB_STORE);
246→
247→      const stored = await new Promise<{
248→        iv: number[];
249→        data: number[];
250→      } | null>((resolve, reject) => {
251→        const request = store.get(IDB_KEY);
252→        request.onsuccess = () => resolve(request.result ?? null);
253→        request.onerror = () => reject(request.error);
254→      });
255→
256→      if (!stored || !stored.iv || !stored.data) return false;
257→
258→      const searchKey = await this.deriveSearchKey(userPrivateKey);
259→      const iv = new Uint8Array(stored.iv);
260→      const ciphertext = new Uint8Array(stored.data);
261→
262→      const plaintext = await crypto.subtle.decrypt(
263→        { name: 'AES-GCM', iv },
264→        searchKey,
265→        ciphertext
266→      );
267→
268→      const serialized = new TextDecoder().decode(plaintext);
269→      const json = JSON.parse(serialized);
270→
271→      this.miniSearch = MiniSearch.loadJSON(JSON.stringify(json), MINISEARCH_OPTIONS);
272→      return true;
273→    } catch (err) {
274→      console.warn('[SearchIndex] Failed to load encrypted index:', err);
275→      return false;
276→    }
277→  }
278→
279→  /**
280→   * Clear the in-memory index and remove the encrypted entry from IndexedDB.
281→   * Call on logout.
282→   */
283→  async clear(): Promise<void> {
284→    this.miniSearch.removeAll();
285→
286→    try {
287→      const db = await openSearchDB();
288→      const tx = db.transaction(IDB_STORE, 'readwrite');
289→      const store = tx.objectStore(IDB_STORE);
290→      store.delete(IDB_KEY);
291→
292→      await new Promise<void>((resolve, reject) => {
293→        tx.oncomplete = () => resolve();
294→        tx.onerror = () => reject(tx.error);
295→      });
296→    } catch (err) {
297→      console.warn('[SearchIndex] Failed to clear IndexedDB entry:', err);
298→    }
299→  }
300→
301→  /** Returns whether the index has any documents */
302→  get isEmpty(): boolean {
303→    return this.miniSearch.documentCount === 0;
304→  }
305→
306→  /** Returns the number of indexed documents */
307→  get size(): number {
308→    return this.miniSearch.documentCount;
309→  }
310→
311→  /** Current index version (increments on each rebuild) */
312→  get version(): number {
313→    return this.indexVersion;
314→  }
315→
316→  // -------------------------------------------------------------------------
317→  // Private helpers
318→  // -------------------------------------------------------------------------
319→
320→  /**
321→   * Build the breadcrumb path for a folder by walking up the parent chain.
322→   */
323→  private buildPath(
324→    folderId: string,
325→    folders: Record<string, FolderNode>
326→  ): string {
327→    const parts: string[] = [];
328→    let currentId: string | null = folderId;
329→    while (currentId) {
330→      const folder = folders[currentId];
331→      if (!folder) break;
332→      parts.unshift(folder.name);
333→      currentId = folder.parentId;
334→    }
335→    return parts.join(' / ');
336→  }
337→
338→  /**
339→   * Derive a dedicated AES-256-GCM key from the user's vault private key
340→   * using HKDF with domain-separated info string.
341→   */
342→  private async deriveSearchKey(
343→    userPrivateKey: Uint8Array
344→  ): Promise<CryptoKey> {
345→    const baseKey = await crypto.subtle.importKey(
346→      'raw',
347→      userPrivateKey,
348→      'HKDF',
349→      false,
350→      ['deriveKey']
351→    );
352→
353→    return crypto.subtle.deriveKey(
354→      {
355→        name: 'HKDF',
356→        hash: 'SHA-256',
357→        salt: new Uint8Array(0),
358→        info: new TextEncoder().encode(HKDF_INFO),
359→      },
360→      baseKey,
361→      { name: 'AES-GCM', length: 256 },
362→      false,
363→      ['encrypt', 'decrypt']
364→    );
365→  }
366→}
367→
368→// ---------------------------------------------------------------------------
369→// Singleton instance
370→// ---------------------------------------------------------------------------
371→
372→export const searchIndexService = new SearchIndexService();
