279→    export function SearchPalette({ ... }: SearchPaletteProps) {
280→      const [selectedIndex, setSelectedIndex] = useState(0);
281→      const inputRef = useRef<HTMLInputElement>(null);
282→      const resultsRef = useRef<HTMLDivElement>(null);
283→
284→      // Reset selection when results change
285→      useEffect(() => setSelectedIndex(0), [results]);
286→
287→      // Focus input when opening
288→      useEffect(() => {
289→        if (isOpen) inputRef.current?.focus();
290→      }, [isOpen]);
291→
292→      // Keyboard navigation
293→      const handleKeyDown = (e: React.KeyboardEvent) => {
294→        switch (e.key) {
295→          case 'ArrowDown':
296→            e.preventDefault();
297→            setSelectedIndex((i) => Math.min(i + 1, results.length - 1));
298→            break;
299→          case 'ArrowUp':
300→            e.preventDefault();
301→            setSelectedIndex((i) => Math.max(i - 1, 0));
302→            break;
303→          case 'Enter':
304→            e.preventDefault();
305→            if (results[selectedIndex]) {
306→              onSelectResult(results[selectedIndex]);
307→            }
308→            break;
309→          case 'Escape':
310→            e.preventDefault();
311→            onClose();
312→            break;
313→        }
314→      };
