316→      // Scroll selected item into view
317→      useEffect(() => {
318→        const container = resultsRef.current;
319→        if (!container) return;
320→        const selected = container.children[selectedIndex] as HTMLElement | undefined;
321→        selected?.scrollIntoView({ block: 'nearest' });
322→      }, [selectedIndex]);
