329→
330→      if (!isOpen) return null;
331→
332→      // File type icon mapping (lucide icon names as Unicode or simple SVG)
333→      // Use simple text-based icons for terminal aesthetic:
334→      // folder -> [D], file -> based on extension
335→      // Actually use lucide-react if available, otherwise CSS-based icons
336→
337→      return (
338→        <div
339→          className="search-backdrop"
340→          ref={backdropRef}
341→          onClick={handleBackdropClick}
342→          role="dialog"
343→          aria-modal="true"
344→          aria-label="Search files"
345→        >
346→          <div className="search-palette" onKeyDown={handleKeyDown}>
347→            {/* Search input */}
348→            <div className="search-input-row">
349→              <span className="search-icon">&#x2315;</span> {/* magnifying glass alternative, or use > prompt */}
350→              <input
351→                ref={inputRef}
352→                className="search-input"
353→                type="text"
354→                placeholder="Search files..."
355→                value={query}
356→                onChange={(e) => onQueryChange(e.target.value)}
357→                autoComplete="off"
358→                spellCheck={false}
359→              />
360→              <span className="search-esc-hint">ESC</span>
361→            </div>
362→
363→            {/* Results area */}
364→            <div className="search-results" ref={resultsRef}>
365→              {isBuilding && (
366→                <div className="search-building">{'// building index...'}</div>
367→              )}
368→              {!isBuilding && isIndexReady && query.trim() && results.length === 0 && (
369→                <div className="search-no-results">
370→                  {'// no results for '}&apos;{query}&apos;
371→                </div>
372→              )}
373→              {results.map((result, index) => (
374→                <SearchResultItem
375→                  key={result.id}
376→                  result={result}
377→                  isSelected={index === selectedIndex}
378→                  onClick={() => onSelectResult(result)}
379→                  onMouseEnter={() => setSelectedIndex(index)}
380→                />
381→              ))}
382→            </div>
383→
384→            {/* Footer with keyboard hints and result count */}
385→            <div className="search-footer">
386→              <span className="search-footer-hints">
387→                <kbd>&uarr;&darr;</kbd> navigate <kbd>&crarr;</kbd> open <kbd>esc</kbd> close
388→              </span>
389→              {results.length > 0 && (
390→                <span className="search-footer-count">
391→                  {'// '}{results.length} result{results.length !== 1 ? 's' : ''}
392→                </span>
393→              )}
394→            </div>
395→          </div>
396→        </div>
397→      );
398→    }
