  1→/**
  2→ * Search Index Service
  3→ *
  4→ * Manages a client-side search index for file and folder names using MiniSearch.
  5→ * The index is encrypted with AES-256-GCM (key derived via HKDF from the user's
  6→ * vault private key) before persisting to IndexedDB for zero-knowledge on-disk storage.
  7→ *
  8→ * This is a pure TypeScript service with no React dependencies.
  9→ */
 10→
 11→import MiniSearch from 'minisearch';
 12→import type { FolderNode } from '../stores/folder.store';
 13→
 14→// ---------------------------------------------------------------------------
 15→// Types
 16→// ---------------------------------------------------------------------------
 17→
 18→/** A document stored in the MiniSearch index. */
 19→type SearchDocument = {
 20→  /** Unique key: `${folderId}:${childId}` (avoids collisions across folders) */
 21→  id: string;
 22→  /** File or folder name (what users search for) */
 23→  name: string;
 24→  /** Whether this is a file or folder */
 25→  type: 'file' | 'folder';
 26→  /** Breadcrumb path like "My Vault / Documents / Reports" */
 27→  parentPath: string;
 28→  /** Folder ID for navigation on result click */
 29→  parentFolderId: string;
 30→  /** Timestamp for display in results (Unix ms) */
 31→  modifiedAt: number;
 32→};
 33→
 34→/** A search result returned by the service. */
 35→export type SearchResult = {
 36→  id: string;
 37→  name: string;
 38→  type: 'file' | 'folder';
 39→  parentPath: string;
 40→  parentFolderId: string;
 41→  modifiedAt: number;
 42→  /** MiniSearch relevance score (higher = better match) */
 43→  score: number;
 44→  /** Match info from MiniSearch, maps field name to matching terms */
 45→  match: Record<string, string[]>;
 46→};
 47→
 48→// ---------------------------------------------------------------------------
 49→// MiniSearch options (shared between constructor and loadJSON)
 50→// ---------------------------------------------------------------------------
 51→
 52→const MINISEARCH_OPTIONS = {
 53→  fields: ['name'],
 54→  storeFields: ['name', 'type', 'parentPath', 'parentFolderId', 'modifiedAt'],
 55→  searchOptions: {
 56→    fuzzy: 0.2,
 57→    prefix: true,
 58→    boost: { name: 1 },
 59→  },
 60→};
 61→
 62→// ---------------------------------------------------------------------------
 63→// IndexedDB constants
 64→// ---------------------------------------------------------------------------
 65→
 66→const IDB_NAME = 'cipherbox-search';
 67→const IDB_VERSION = 1;
 68→const IDB_STORE = 'index';
 69→const IDB_KEY = 'encrypted-index';
 70→
 71→// ---------------------------------------------------------------------------
 72→// HKDF constants
 73→// ---------------------------------------------------------------------------
 74→
 75→const HKDF_INFO = 'cipherbox-search-index-v1';
 76→
 77→// ---------------------------------------------------------------------------
 78→// IndexedDB helpers (follows pattern from device/identity.ts)
 79→// ---------------------------------------------------------------------------
 80→
 81→function openSearchDB(): Promise<IDBDatabase> {
 82→  return new Promise((resolve, reject) => {
 83→    const request = indexedDB.open(IDB_NAME, IDB_VERSION);
 84→    request.onupgradeneeded = () => {
 85→      request.result.createObjectStore(IDB_STORE);
 86→    };
 87→    request.onsuccess = () => resolve(request.result);
 88→    request.onerror = () => reject(request.error);
 89→  });
 90→}
 91→
 92→// ---------------------------------------------------------------------------
 93→// SearchIndexService
 94→// ---------------------------------------------------------------------------
 95→
 96→export class SearchIndexService {
 97→  private miniSearch: MiniSearch<SearchDocument>;
 98→  private indexVersion: number = 0;
 99→
100→  constructor() {
101→    this.miniSearch = new MiniSearch<SearchDocument>(MINISEARCH_OPTIONS);
102→  }
103→
104→  /**
105→   * Build the full index from the folder store's folder tree.
106→   * Walks all loaded FolderNodes and indexes their children (files and folders).
107→   *
108→   * @param folders - Record<string, FolderNode> from folder store
109→   */
110→  buildFromFolderTree(folders: Record<string, FolderNode>): void {
111→    this.miniSearch.removeAll();
112→
113→    const documents: SearchDocument[] = [];
114→
115→    for (const folder of Object.values(folders)) {
116→      const parentPath = this.buildPath(folder.id, folders);
117→
118→      // Index each child (files and subfolders)
119→      for (const child of folder.children) {
120→        documents.push({
121→          id: `${folder.id}:${child.id}`,
122→          name: child.name,
123→          type: child.type === 'folder' ? 'folder' : 'file',
124→          parentPath,
125→          parentFolderId: folder.id,
126→          modifiedAt: child.modifiedAt ?? child.createdAt ?? 0,
127→        });
128→      }
129→    }
130→
131→    // Also index folders themselves (except root) as searchable items.
132→    // A folder's parent is its parentId, so it appears in search under
133→    // the parent folder's path.
134→    for (const folder of Object.values(folders)) {
135→      if (!folder.parentId) continue; // skip root
136→      const parentFolder = folders[folder.parentId];
137→      if (!parentFolder) continue;
138→
139→      const parentPath = this.buildPath(folder.parentId, folders);
140→
141→      // Use the folder's own id with a "self:" prefix to avoid collision
142→      // with the same folder appearing as a child entry
143→      documents.push({
144→        id: `${folder.parentId}:${folder.id}`,
145→        name: folder.name,
146→        type: 'folder',
147→        parentPath,
148→        parentFolderId: folder.parentId,
149→        modifiedAt: 0, // folders don't have a top-level modifiedAt
150→      });
151→    }
152→
153→    // Deduplicate: children already include subfolder entries from parent.
154→    // The folder-self entries above may overlap with child entries.
155→    // Use a Map to keep only one document per id.
156→    const deduped = new Map<string, SearchDocument>();
157→    for (const doc of documents) {
158→      deduped.set(doc.id, doc);
159→    }
160→
161→    this.miniSearch.addAll(Array.from(deduped.values()));
162→    this.indexVersion++;
163→  }
164→
165→  /**
166→   * Search the index with fuzzy matching.
167→   *
168→   * @param query - user's search string
169→   * @returns Array of SearchResult sorted by relevance score (descending)
170→   */
171→  search(query: string): SearchResult[] {
172→    if (!query.trim()) return [];
173→
174→    const results = this.miniSearch.search(query);
175→
176→    return results.map((result) => ({
177→      id: result.id as string,
178→      name: result.name as string,
179→      type: result.type as 'file' | 'folder',
180→      parentPath: result.parentPath as string,
181→      parentFolderId: result.parentFolderId as string,
182→      modifiedAt: result.modifiedAt as number,
183→      score: result.score,
184→      match: result.match,
185→    }));
186→  }
187→
188→  /**
189→   * Persist the current index to IndexedDB, encrypted with a key derived
190→   * from the user's vault private key via HKDF.
191→   *
192→   * @param userPrivateKey - user's secp256k1 private key (32 bytes) for HKDF derivation
193→   */
194→  async persistEncrypted(userPrivateKey: Uint8Array): Promise<void> {
195→    try {
196→      const searchKey = await this.deriveSearchKey(userPrivateKey);
197→      const serialized = JSON.stringify(this.miniSearch.toJSON());
198→      const plaintext = new TextEncoder().encode(serialized);
199→
200→      const iv = crypto.getRandomValues(new Uint8Array(12));
201→      const ciphertext = await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, searchKey, plaintext);
202→
203→      const db = await openSearchDB();
204→      const tx = db.transaction(IDB_STORE, 'readwrite');
205→      const store = tx.objectStore(IDB_STORE);
206→
207→      // Store as number[] for cross-browser IndexedDB compatibility
208→      store.put(
209→        {
210→          iv: Array.from(iv),
211→          data: Array.from(new Uint8Array(ciphertext)),
212→        },
213→        IDB_KEY
214→      );
215→
216→      await new Promise<void>((resolve, reject) => {
217→        tx.oncomplete = () => resolve();
218→        tx.onerror = () => reject(tx.error);
219→      });
220→    } catch (err) {
221→      console.warn('[SearchIndex] Failed to persist encrypted index:', err);
222→    }
223→  }
224→
225→  /**
226→   * Load the index from IndexedDB and decrypt.
227→   *
228→   * @param userPrivateKey - user's secp256k1 private key (32 bytes) for HKDF derivation
229→   * @returns true if index was loaded successfully, false if not found or decryption failed
230→   */
231→  async loadEncrypted(userPrivateKey: Uint8Array): Promise<boolean> {
232→    try {
233→      const db = await openSearchDB();
234→      const tx = db.transaction(IDB_STORE, 'readonly');
235→      const store = tx.objectStore(IDB_STORE);
236→
237→      const stored = await new Promise<{
238→        iv: number[];
239→        data: number[];
240→      } | null>((resolve, reject) => {
241→        const request = store.get(IDB_KEY);
242→        request.onsuccess = () => resolve(request.result ?? null);
243→        request.onerror = () => reject(request.error);
244→      });
245→
246→      if (!stored || !stored.iv || !stored.data) return false;
247→
248→      const searchKey = await this.deriveSearchKey(userPrivateKey);
249→      const iv = new Uint8Array(stored.iv);
250→      const ciphertext = new Uint8Array(stored.data);
251→
252→      const plaintext = await crypto.subtle.decrypt({ name: 'AES-GCM', iv }, searchKey, ciphertext);
253→
254→      const serialized = new TextDecoder().decode(plaintext);
255→      const json = JSON.parse(serialized);
256→
257→      this.miniSearch = MiniSearch.loadJSON(JSON.stringify(json), MINISEARCH_OPTIONS);
258→      return true;
259→    } catch (err) {
260→      console.warn('[SearchIndex] Failed to load encrypted index:', err);
261→      return false;
262→    }
263→  }
264→
265→  /**
266→   * Clear the in-memory index and remove the encrypted entry from IndexedDB.
267→   * Call on logout.
268→   */
269→  async clear(): Promise<void> {
270→    this.miniSearch.removeAll();
271→
272→    try {
273→      const db = await openSearchDB();
274→      const tx = db.transaction(IDB_STORE, 'readwrite');
275→      const store = tx.objectStore(IDB_STORE);
276→      store.delete(IDB_KEY);
277→
278→      await new Promise<void>((resolve, reject) => {
279→        tx.oncomplete = () => resolve();
280→        tx.onerror = () => reject(tx.error);
281→      });
282→    } catch (err) {
283→      console.warn('[SearchIndex] Failed to clear IndexedDB entry:', err);
284→    }
285→  }
286→
287→  /** Returns whether the index has any documents */
288→  get isEmpty(): boolean {
289→    return this.miniSearch.documentCount === 0;
290→  }
291→
292→  /** Returns the number of indexed documents */
293→  get size(): number {
294→    return this.miniSearch.documentCount;
295→  }
296→
297→  /** Current index version (increments on each rebuild) */
298→  get version(): number {
299→    return this.indexVersion;
300→  }
301→
302→  // -------------------------------------------------------------------------
303→  // Private helpers
304→  // -------------------------------------------------------------------------
305→
306→  /**
307→   * Build the breadcrumb path for a folder by walking up the parent chain.
308→   */
309→  private buildPath(folderId: string, folders: Record<string, FolderNode>): string {
310→    const parts: string[] = [];
311→    let currentId: string | null = folderId;
312→    while (currentId) {
313→      const node: FolderNode | undefined = folders[currentId];
314→      if (!node) break;
315→      parts.unshift(node.name);
316→      currentId = node.parentId;
317→    }
318→    return parts.join(' / ');
319→  }
320→
321→  /**
322→   * Derive a dedicated AES-256-GCM key from the user's vault private key
323→   * using HKDF with domain-separated info string.
324→   */
325→  private async deriveSearchKey(userPrivateKey: Uint8Array): Promise<CryptoKey> {
326→    const baseKey = await crypto.subtle.importKey(
327→      'raw',
328→      userPrivateKey as BufferSource,
329→      'HKDF',
330→      false,
331→      ['deriveKey']
332→    );
333→
334→    return crypto.subtle.deriveKey(
335→      {
336→        name: 'HKDF',
337→        hash: 'SHA-256',
338→        salt: new Uint8Array(0),
339→        info: new TextEncoder().encode(HKDF_INFO),
340→      },
341→      baseKey,
342→      { name: 'AES-GCM', length: 256 },
343→      false,
344→      ['encrypt', 'decrypt']
345→    );
346→  }
347→}
