 102→/**
 103→ * Check if a filename has a text-editable extension.
 104→ */
 105→function isTextFile(name: string): boolean {
 106→  const lower = name.toLowerCase();
 107→  // Handle dotfiles like .gitignore, .editorconfig
 108→  if (TEXT_EXTENSIONS.has(lower)) return true;
 109→  // Handle well-known extensionless filenames like Dockerfile, Makefile
 110→  if (TEXT_FILENAMES.has(lower)) return true;
 111→  const lastDot = lower.lastIndexOf('.');
 112→  if (lastDot === -1) return false;
 113→  return TEXT_EXTENSIONS.has(lower.slice(lastDot));
 114→}
