 307→  // External drag state — tracks when files from OS are being dragged over
 308→  const [isDraggingExternal, setIsDraggingExternal] = useState(false);
 309→  const dragCounterRef = useRef(0);
 310→
 311→  /**
 312→   * Detect external file drag entering the content area.
 313→   * Uses a counter to handle nested dragenter/dragleave events correctly.
 314→   */
 315→  const handleContentDragEnter = useCallback((e: DragEvent) => {
 316→    if (isExternalFileDrag(e.dataTransfer)) {
 317→      dragCounterRef.current += 1;
 318→      if (dragCounterRef.current === 1) {
 319→        setIsDraggingExternal(true);
 320→      }
 321→    }
 322→  }, []);
 323→
 324→  const handleContentDragOver = useCallback((e: DragEvent) => {
 325→    if (isExternalFileDrag(e.dataTransfer)) {
