 328→    }
 329→  }, []);
 330→
 331→  const handleContentDragLeave = useCallback((e: DragEvent) => {
 332→    if (isExternalFileDrag(e.dataTransfer)) {
 333→      dragCounterRef.current -= 1;
 334→      if (dragCounterRef.current <= 0) {
 335→        dragCounterRef.current = 0;
 336→        setIsDraggingExternal(false);
 337→      }
 338→    }
 339→  }, []);
