 343→  useEffect(() => {
 344→    const resetDragState = () => {
 345→      dragCounterRef.current = 0;
 346→      setIsDraggingExternal(false);
 347→    };
 348→    const handleWindowDrop = (e: Event) => {
 349→      e.preventDefault();
 350→      resetDragState();
 351→    };
 352→    const handleWindowDragLeave = (e: globalThis.DragEvent) => {
 353→      // relatedTarget is null when the drag leaves the browser window entirely
 354→      if (!e.relatedTarget) {
 355→        resetDragState();
 356→      }
 357→    };
 358→    window.addEventListener('dragend', resetDragState);
 359→    window.addEventListener('drop', handleWindowDrop);
 360→    window.addEventListener('dragleave', handleWindowDragLeave as EventListener);
 361→    return () => {
 362→      window.removeEventListener('dragend', resetDragState);
 363→      window.removeEventListener('drop', handleWindowDrop);
 364→      window.removeEventListener('dragleave', handleWindowDragLeave as EventListener);
 365→    };
 366→  }, []);
