 480→          return a.name.localeCompare(b.name, undefined, { sensitivity: 'base' });
 481→        });
 482→
 483→        const ids = sortedChildren.map((c) => c.id);
 484→        const startIdx = ids.indexOf(lastSelectedIdRef.current);
 485→        const endIdx = ids.indexOf(itemId);
