 798→
 799→  const closeRenameDialog = useCallback(() => {
 800→    setRenameDialog({ open: false, item: null });
 801→  }, []);
 802→
 803→  const closeMoveDialog = useCallback(() => {
 804→    setMoveDialog({ open: false, item: null });
 805→  }, []);
 806→
 807→  const closeDetailsDialog = useCallback(() => {
