 814→
 815→  const closeEditorDialog = useCallback(() => {
 816→    setEditorDialog({ open: false, item: null });
 817→  }, []);
 818→
 819→  const closeImagePreviewDialog = useCallback(() => {
 820→    setImagePreviewDialog({ open: false, item: null });
 821→  }, []);
 822→
 823→  const closePdfPreviewDialog = useCallback(() => {
 824→    setPdfPreviewDialog({ open: false, item: null });
 825→  }, []);
 826→
 827→  const closeAudioPlayerDialog = useCallback(() => {
 828→    setAudioPlayerDialog({ open: false, item: null });
