import { useState, useCallback, useEffect, useRef } from 'react';
import { useFolderStore } from '../stores/folder.store';
import { useAuthStore } from '../stores/auth.store';
import { searchIndexService, type SearchResult } from '../services/search-index.service';

// ---------------------------------------------------------------------------
// Module-level callback for triggering index rebuild from outside React tree
// ---------------------------------------------------------------------------

let _rebuildCallback: (() => void) | null = null;

export function registerRebuildCallback(cb: () => void): void {
  _rebuildCallback = cb;
}

export function triggerSearchIndexRebuild(): void {
  _rebuildCallback?.();
}

// ---------------------------------------------------------------------------
// useSearch hook
// ---------------------------------------------------------------------------

/**
 * React hook bridging SearchIndexService with UI state.
 *
 * Manages the search lifecycle: opening/closing the palette, building/loading
 * the index, querying with debounce, and persisting encrypted state.
 *
 * Global keyboard shortcut Cmd/Ctrl+K toggles the palette.
 * Index auto-clears on logout via auth state watcher.
 */
export function useSearch() {
  // State
  const [isOpen, setIsOpen] = useState(false);
  const [query, setQuery] = useState('');
  const [results, setResults] = useState<SearchResult[]>([]);
  const [isIndexReady, setIsIndexReady] = useState(false);
  const [isBuilding, setIsBuilding] = useState(false);

  // Refs
  const hasLoadedFromDb = useRef(false);

  // Store access
  const vaultKeypair = useAuthStore((s) => s.vaultKeypair);
  const isAuthenticated = useAuthStore((s) => s.isAuthenticated);
  const prevAuth = useRef(isAuthenticated);

  // Open the palette
  const open = useCallback(() => setIsOpen(true), []);
  const close = useCallback(() => {
    setIsOpen(false);
    setQuery('');
    setResults([]);
  }, []);
  const toggle = useCallback(() => {
    setIsOpen((prev) => {
      if (prev) {
        setQuery('');
        setResults([]);
      }
      return !prev;
    });
  }, []);

  // Global keyboard shortcut: Cmd/Ctrl+K
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
        e.preventDefault();
        toggle();
      }
    };
    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, [toggle]);

  // Build/load index when palette opens for the first time
  useEffect(() => {
    if (!isOpen || isIndexReady || isBuilding) return;
    if (!vaultKeypair) return;

    const init = async () => {
      setIsBuilding(true);
      try {
        // Try loading from encrypted IndexedDB first
        if (!hasLoadedFromDb.current) {
          const loaded = await searchIndexService.loadEncrypted(vaultKeypair.privateKey);
          hasLoadedFromDb.current = true;
          if (loaded && !searchIndexService.isEmpty) {
            setIsIndexReady(true);
            setIsBuilding(false);
            return;
          }
        }

        // Build fresh from folder store
        const currentFolders = useFolderStore.getState().folders;
        searchIndexService.buildFromFolderTree(currentFolders);
        setIsIndexReady(true);

        // Persist encrypted (fire-and-forget)
        searchIndexService.persistEncrypted(vaultKeypair.privateKey).catch((err) => {
          console.warn('[search] Failed to persist index:', err);
        });
      } catch (err) {
        console.error('[search] Failed to initialize index:', err);
        // Still mark ready -- search works in-memory even if persistence fails
        setIsIndexReady(true);
      } finally {
        setIsBuilding(false);
      }
    };
    init();
  }, [isOpen, isIndexReady, isBuilding, vaultKeypair]);

  // Search with debounce (150ms)
  useEffect(() => {
    if (!isOpen || !isIndexReady) return;
    if (!query.trim()) {
      setResults([]);
      return;
    }

    const timer = setTimeout(() => {
      const searchResults = searchIndexService.search(query.trim());
      setResults(searchResults);
    }, 150);

    return () => clearTimeout(timer);
  }, [query, isOpen, isIndexReady]);

  // Rebuild index method (called after sync detects changes)
  const rebuildIndex = useCallback(() => {
    if (!vaultKeypair) return;
    const currentFolders = useFolderStore.getState().folders;
    searchIndexService.buildFromFolderTree(currentFolders);
    setIsIndexReady(true);

    // Re-persist (fire-and-forget)
    searchIndexService.persistEncrypted(vaultKeypair.privateKey).catch((err) => {
      console.warn('[search] Failed to persist index after rebuild:', err);
    });
  }, [vaultKeypair]);

  // Register rebuild callback so FileBrowser can trigger it
  useEffect(() => {
    registerRebuildCallback(rebuildIndex);
    return () => {
      registerRebuildCallback(() => {});
    };
  }, [rebuildIndex]);

  // Clear index (called on logout)
  const clearIndex = useCallback(async () => {
    try {
      await searchIndexService.clear();
    } catch (err) {
      console.warn('[search] Failed to clear index:', err);
    }
    setIsIndexReady(false);
    hasLoadedFromDb.current = false;
    setIsOpen(false);
    setQuery('');
    setResults([]);
  }, []);

  // Auto-clear on logout: when isAuthenticated transitions true -> false
  useEffect(() => {
    if (prevAuth.current && !isAuthenticated) {
      clearIndex();
    }
    prevAuth.current = isAuthenticated;
  }, [isAuthenticated, clearIndex]);

  return {
    isOpen,
    query,
    setQuery,
    results,
    isIndexReady,
    isBuilding,
    open,
    close,
    toggle,
    rebuildIndex,
    clearIndex,
    resultCount: results.length,
  };
}

export type { SearchResult };

import { useState, useEffect, useRef, type ReactNode } from 'react';
import type { SearchResult } from '../../services/search-index.service';
import '../../styles/search-palette.css';

// ---------------------------------------------------------------------------
// Helper functions
// ---------------------------------------------------------------------------

/**
 * Return a terminal-aesthetic icon for a file or folder.
 * Uses Unicode characters that render well in JetBrains Mono.
 */
function getFileIcon(name: string, type: 'file' | 'folder'): string {
  if (type === 'folder') return '\u{1F5C0}'; // folder icon

  const lower = name.toLowerCase();
  const lastDot = lower.lastIndexOf('.');
  if (lastDot === -1) return '\u{1F5CE}'; // generic file

  const ext = lower.slice(lastDot);

  // Image
  if (['.png', '.jpg', '.jpeg', '.gif', '.webp', '.svg', '.bmp', '.ico', '.avif'].includes(ext)) {
    return '\u{1F5BC}'; // framed picture
  }
  // Video
  if (['.mp4', '.webm', '.mov', '.mkv'].includes(ext)) {
    return '\u{1F3AC}'; // clapper board
  }
  // Audio
  if (['.mp3', '.wav', '.ogg', '.m4a', '.flac'].includes(ext)) {
    return '\u{266B}'; // beamed eighth notes
  }
  // Document / PDF
  if (ext === '.pdf') {
    return '\u{1F4C4}'; // page facing up
  }
  // Code / text
  if (
    [
      '.ts', '.tsx', '.js', '.jsx', '.py', '.rs', '.go', '.java', '.c', '.cpp', '.h',
      '.html', '.css', '.json', '.yaml', '.yml', '.xml', '.toml', '.sh', '.md', '.txt',
    ].includes(ext)
  ) {
    return '\u{1F4DD}'; // memo
  }

  return '\u{1F5CE}'; // generic file
}

/**
 * Format a timestamp for display.
 * Within current year: "Feb 24". Older: "Feb 24, 2025". Falsy: "".
 */
function formatRelativeDate(timestamp: number): string {
  if (!timestamp) return '';

  const date = new Date(timestamp);
  const now = new Date();
  const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

  const month = months[date.getMonth()];
  const day = date.getDate();

  if (date.getFullYear() === now.getFullYear()) {
    return `${month} ${day}`;
  }
  return `${month} ${day}, ${date.getFullYear()}`;
}

/**
 * Highlight matching substrings in a name using MiniSearch match info.
 * Falls back to rendering the name without highlights if match info is unavailable.
 */
function highlightMatches(name: string, match: Record<string, string[]>): ReactNode {
  // Collect matched terms from the 'name' field
  const terms = match?.name ?? [];
  if (terms.length === 0) return name;

  // Build a set of character indices that are part of a match
  const matchedIndices = new Set<number>();
  const lower = name.toLowerCase();

  for (const term of terms) {
    const termLower = term.toLowerCase();
    let startPos = 0;
    // Find all occurrences of the term in the name
    while (startPos < lower.length) {
      const idx = lower.indexOf(termLower, startPos);
      if (idx === -1) break;
      for (let i = idx; i < idx + termLower.length; i++) {
        matchedIndices.add(i);
      }
      startPos = idx + 1;
    }
  }

  if (matchedIndices.size === 0) return name;

  // Build segments: consecutive matched/unmatched characters
  const segments: ReactNode[] = [];
  let i = 0;
  while (i < name.length) {
    const isMatch = matchedIndices.has(i);
    let j = i;
    while (j < name.length && matchedIndices.has(j) === isMatch) {
      j++;
    }
    const segment = name.slice(i, j);
    if (isMatch) {
      segments.push(<mark key={i}>{segment}</mark>);
    } else {
      segments.push(segment);
    }
    i = j;
  }

  return <>{segments}</>;
}

// ---------------------------------------------------------------------------
// SearchResultItem
// ---------------------------------------------------------------------------

function SearchResultItem({
  result,
  isSelected,
  onClick,
  onMouseEnter,
}: {
  result: SearchResult;
  isSelected: boolean;
  onClick: () => void;
  onMouseEnter: () => void;
}) {
  const icon = getFileIcon(result.name, result.type);
  const dateStr = formatRelativeDate(result.modifiedAt);
  const highlightedName = highlightMatches(result.name, result.match);

  return (
    <div
      className={`search-result-item ${isSelected ? 'selected' : ''}`}
      onClick={onClick}
      onMouseEnter={onMouseEnter}
      role="option"
      aria-selected={isSelected}
    >
      <span className={`search-result-icon ${isSelected ? 'icon-bright' : ''}`}>{icon}</span>
      <div className="search-result-info">
        <span className="search-result-name">{highlightedName}</span>
        <span className="search-result-path">{result.parentPath}</span>
      </div>
      {dateStr && <span className="search-result-date">{dateStr}</span>}
    </div>
  );
}

// ---------------------------------------------------------------------------
// SearchPalette
// ---------------------------------------------------------------------------

interface SearchPaletteProps {
  isOpen: boolean;
  query: string;
  onQueryChange: (q: string) => void;
  results: SearchResult[];
  resultCount: number;
  isBuilding: boolean;
  isIndexReady: boolean;
  onClose: () => void;
  onSelectResult: (result: SearchResult) => void;
}

/**
 * Command palette overlay for searching files and folders.
 *
 * Keyboard-first design: arrow keys navigate results, Enter opens,
 * Escape closes. Click outside backdrop also dismisses.
 *
 * Terminal aesthetic: JetBrains Mono, green on black, sharp corners.
 */
export function SearchPalette({
  isOpen,
  query,
  onQueryChange,
  results,
  resultCount,
  isBuilding,
  isIndexReady,
  onClose,
  onSelectResult,
}: SearchPaletteProps) {
  const [selectedIndex, setSelectedIndex] = useState(0);
  const inputRef = useRef<HTMLInputElement>(null);
  const resultsRef = useRef<HTMLDivElement>(null);
  const backdropRef = useRef<HTMLDivElement>(null);

  // Reset selection when results change
  useEffect(() => setSelectedIndex(0), [results]);

  // Focus input when opening
  useEffect(() => {
    if (isOpen) inputRef.current?.focus();
  }, [isOpen]);

  // Scroll selected item into view
  useEffect(() => {
    const container = resultsRef.current;
    if (!container) return;
    const selected = container.children[selectedIndex] as HTMLElement | undefined;
    selected?.scrollIntoView({ block: 'nearest' });
  }, [selectedIndex]);

  // Keyboard navigation
  const handleKeyDown = (e: React.KeyboardEvent) => {
    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault();
        setSelectedIndex((i) => Math.min(i + 1, results.length - 1));
        break;
      case 'ArrowUp':
        e.preventDefault();
        setSelectedIndex((i) => Math.max(i - 1, 0));
        break;
      case 'Enter':
        e.preventDefault();
        if (results[selectedIndex]) {
          onSelectResult(results[selectedIndex]);
        }
        break;
      case 'Escape':
        e.preventDefault();
        onClose();
        break;
    }
  };

  // Click outside to close
  const handleBackdropClick = (e: React.MouseEvent) => {
    if (e.target === backdropRef.current) onClose();
  };

  if (!isOpen) return null;

  return (
    <div
      className="search-backdrop"
      ref={backdropRef}
      onClick={handleBackdropClick}
      role="dialog"
      aria-modal="true"
      aria-label="Search files"
    >
      <div className="search-palette" onKeyDown={handleKeyDown}>
        {/* Search input */}
        <div className="search-input-row">
          <span className="search-icon">&gt;_</span>
          <input
            ref={inputRef}
            className="search-input"
            type="text"
            placeholder="Search files..."
            value={query}
            onChange={(e) => onQueryChange(e.target.value)}
            autoComplete="off"
            spellCheck={false}
          />
          <span className="search-esc-hint">ESC</span>
        </div>

        {/* Results area */}
        <div className="search-results" ref={resultsRef} role="listbox" aria-label="Search results">
          {isBuilding && (
            <div className="search-building">{'// building index...'}</div>
          )}
          {!isBuilding && isIndexReady && query.trim() && results.length === 0 && (
            <div className="search-no-results">
              {'// no results for \''}{query}{'\''}
            </div>
          )}
          {results.map((result, index) => (
            <SearchResultItem
              key={result.id}
              result={result}
              isSelected={index === selectedIndex}
              onClick={() => onSelectResult(result)}
              onMouseEnter={() => setSelectedIndex(index)}
            />
          ))}
        </div>

        {/* Footer with keyboard hints and result count */}
        <div className="search-footer">
          <span className="search-footer-hints">
            <kbd>{'\u2191\u2193'}</kbd> navigate <kbd>{'\u21B5'}</kbd> open <kbd>esc</kbd> close
          </span>
          {resultCount > 0 && (
            <span className="search-footer-count">
              {'// '}{resultCount} result{resultCount !== 1 ? 's' : ''}
            </span>
          )}
        </div>
      </div>
    </div>
  );
}

/* ==========================================================================
   Search Palette - Command Palette Overlay
   Terminal aesthetic: JetBrains Mono, green on black, sharp corners
   ========================================================================== */

/* Backdrop */
.search-backdrop {
  position: fixed;
  inset: 0;
  background: rgb(0 0 0 / 80%);
  z-index: 100;
  display: flex;
  justify-content: center;
  padding-top: 120px;
}

/* Palette container */
.search-palette {
  width: 600px;
  max-height: calc(100vh - 200px);
  background: var(--color-black);
  border: 1px solid var(--color-green-primary);
  border-radius: 0;
  display: flex;
  flex-direction: column;
  font-family: var(--font-family-mono);
  overflow: hidden;
  align-self: flex-start;
}

/* Search input row */
.search-input-row {
  display: flex;
  align-items: center;
  padding: 12px 16px;
  border-bottom: 1px solid var(--color-border-dim);
  gap: 8px;
}

.search-icon {
  color: var(--color-text-secondary);
  font-size: 14px;
  flex-shrink: 0;
}

.search-input {
  flex: 1;
  background: none;
  border: none;
  color: var(--color-text-primary);
  font-family: var(--font-family-mono);
  font-size: 14px;
  outline: none;
  caret-color: var(--color-green-primary);
}

.search-input::placeholder {
  color: var(--color-text-dim);
}

.search-input:focus-visible {
  outline: none;
}

.search-esc-hint {
  color: var(--color-text-dim);
  font-size: 10px;
  border: 1px solid var(--color-text-dim);
  padding: 1px 4px;
  flex-shrink: 0;
}

/* Results */
.search-results {
  flex: 1;
  overflow-y: auto;
  max-height: 400px;
}

.search-result-item {
  display: flex;
  align-items: center;
  padding: 8px 16px;
  cursor: pointer;
  gap: 10px;
  border-left: 2px solid transparent;
}

.search-result-item:hover,
.search-result-item.selected {
  background: var(--color-nav-active);
  border-left-color: var(--color-green-primary);
}

.search-result-icon {
  color: var(--color-text-secondary);
  font-size: 14px;
  flex-shrink: 0;
  width: 20px;
  text-align: center;
}

.search-result-item.selected .search-result-icon,
.search-result-icon.icon-bright {
  color: var(--color-green-primary);
}

.search-result-info {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.search-result-name {
  color: var(--color-text-primary);
  font-size: 12px;
  font-weight: var(--font-weight-bold);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.search-result-name mark {
  background: none;
  color: var(--color-green-primary);
  text-decoration: underline;
}

.search-result-path {
  color: var(--color-text-dim);
  font-size: 10px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.search-result-date {
  color: var(--color-text-dim);
  font-size: 10px;
  flex-shrink: 0;
  text-align: right;
}

/* Empty/building states */
.search-building,
.search-no-results {
  padding: 24px 16px;
  color: var(--color-text-dim);
  font-size: 12px;
  text-align: center;
}

/* Footer */
.search-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 16px;
  border-top: 1px solid var(--color-border-dim);
}

.search-footer-hints {
  color: var(--color-text-dim);
  font-size: 10px;
}

.search-footer-hints kbd {
  display: inline;
  font-family: var(--font-family-mono);
  font-size: 10px;
  color: var(--color-text-secondary);
}

.search-footer-count {
  color: var(--color-text-dim);
  font-size: 10px;
}

/* ==========================================================================
   Responsive
   ========================================================================== */

@media (max-width: 768px) {
  .search-palette {
    width: calc(100vw - 32px);
  }

  .search-backdrop {
    padding-top: 80px;
  }
}

