253→  const handleSync = useCallback(async () => {
254→    if (!rootIpnsName) return;
255→
256→    // Resolve root folder IPNS to get remote CID and sequence number
257→    // Note: resolveIpnsRecord returns null when the record definitively
258→    // doesn't exist (backend 404 / success:false). Transient failures
259→    // (network errors, 5xx) throw instead, which useSyncPolling catches.
260→    const resolved = await resolveIpnsRecord(rootIpnsName);
261→    if (!resolved) {
262→      // No IPNS record found. This is expected for vaults that have
263→      // never published (empty vault, no uploads yet). Return normally
264→      // so useSyncPolling marks initial sync complete and shows the
265→      // empty file browser instead of retrying forever.
266→      return;
267→    }
268→
269→    // Read fresh state from store — avoid stale closure from render cycle.
270→    // On initial load, the root folder may not be in the closure's `folders`
271→    // yet because useFolderNavigation's useEffect sets it in the same commit.
272→    const rootFolder = useFolderStore.getState().folders['root'];
273→    if (!rootFolder) return;
274→
275→    // Compare sequence numbers - if remote > local, we need to refresh
276→    // Sequence number comparison is more reliable than CID since we
277→    // don't cache the local CID, and sequence always increments
278→    if (resolved.sequenceNumber <= rootFolder.sequenceNumber) {
279→      // No changes, already up to date
280→      return;
281→    }
282→
283→    // Remote has newer version - fetch and decrypt new metadata
284→    try {
285→      const metadata = await fetchAndDecryptMetadata(resolved.cid, rootFolder.folderKey);
286→
287→      // Update folder store with new children
288→      // Per CONTEXT.md: last write wins, instant refresh (no toast/prompt)
289→      useFolderStore.getState().updateFolderChildren('root', metadata.children);
290→      useFolderStore.getState().updateFolderSequence('root', resolved.sequenceNumber);
291→    } catch (err) {
292→      console.error('Sync refresh failed:', err);
293→      // During initial sync, propagate so useSyncPolling keeps the
294→      // loading UI visible and retries instead of showing empty state
295→      if (!useSyncStore.getState().initialSyncComplete) {
296→        throw err;
297→      }
298→    }
299→  }, [rootIpnsName]);
300→
301→  // Start sync polling (30s interval, pauses when backgrounded/offline)
302→  useSyncPolling(handleSync);

