106→    **1. Create `apps/web/src/hooks/useSearch.ts`**
107→
108→    This hook manages the search lifecycle: opening/closing the palette, building/loading the index, querying, and persisting.
109→
110→    ```typescript
111→    export function useSearch() {
112→      // State
113→      const [isOpen, setIsOpen] = useState(false);
114→      const [query, setQuery] = useState('');
115→      const [results, setResults] = useState<SearchResult[]>([]);
116→      const [isIndexReady, setIsIndexReady] = useState(false);
117→      const [isBuilding, setIsBuilding] = useState(false);
118→
119→      // Refs
120→      const hasLoadedFromDb = useRef(false);
121→
122→      // Store access
123→      const folders = useFolderStore((s) => s.folders);
124→      const vaultKeypair = useAuthStore((s) => s.vaultKeypair);
125→
126→      // Open the palette
127→      const open = useCallback(() => setIsOpen(true), []);
128→      const close = useCallback(() => {
129→        setIsOpen(false);
130→        setQuery('');
131→        setResults([]);
132→      }, []);
133→      const toggle = useCallback(() => {
134→        setIsOpen((prev) => {
135→          if (prev) {
136→            setQuery('');
137→            setResults([]);
138→          }
139→          return !prev;
140→        });
141→      }, []);
142→
143→      // Global keyboard shortcut: Cmd/Ctrl+K
144→      useEffect(() => {
145→        const handler = (e: KeyboardEvent) => {
146→          if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
147→            e.preventDefault();
148→            toggle();
149→          }
150→        };
151→        window.addEventListener('keydown', handler);
152→        return () => window.removeEventListener('keydown', handler);
153→      }, [toggle]);
154→
155→      // Build/load index when palette opens for the first time
156→      useEffect(() => {
157→        if (!isOpen || isIndexReady || isBuilding) return;
158→        if (!vaultKeypair) return;
159→
160→        const init = async () => {
161→          setIsBuilding(true);
162→          try {
163→            // Try loading from encrypted IndexedDB first
164→            if (!hasLoadedFromDb.current) {
165→              const loaded = await searchIndexService.loadEncrypted(vaultKeypair.privateKey);
166→              hasLoadedFromDb.current = true;
167→              if (loaded && !searchIndexService.isEmpty) {
168→                setIsIndexReady(true);
169→                setIsBuilding(false);
170→                return;
171→              }
172→            }
173→
174→            // Build fresh from folder store
175→            const currentFolders = useFolderStore.getState().folders;
176→            searchIndexService.buildFromFolderTree(currentFolders);
177→            setIsIndexReady(true);
178→
179→            // Persist encrypted (fire-and-forget)
180→            searchIndexService.persistEncrypted(vaultKeypair.privateKey).catch((err) => {
181→              console.warn('[search] Failed to persist index:', err);
182→            });
183→          } catch (err) {
184→            console.error('[search] Failed to initialize index:', err);
185→            // Still mark ready -- search works in-memory even if persistence fails
186→            setIsIndexReady(true);
187→          } finally {
188→            setIsBuilding(false);
189→          }
190→        };
191→        init();
192→      }, [isOpen, isIndexReady, isBuilding, vaultKeypair]);
193→
194→      // Search with debounce (150ms)
195→      useEffect(() => {
196→        if (!isOpen || !isIndexReady) return;
197→        if (!query.trim()) {
198→          setResults([]);
199→          return;
200→        }
201→
202→        const timer = setTimeout(() => {
203→          const results = searchIndexService.search(query.trim());
204→          setResults(results);
205→        }, 150);
206→
207→        return () => clearTimeout(timer);
208→      }, [query, isOpen, isIndexReady]);
209→
210→      // Rebuild index method (called after sync detects changes)
211→      const rebuildIndex = useCallback(() => {
212→        if (!vaultKeypair) return;
213→        const currentFolders = useFolderStore.getState().folders;
214→        searchIndexService.buildFromFolderTree(currentFolders);
215→        setIsIndexReady(true);
216→
217→        // Re-persist (fire-and-forget)
218→        searchIndexService.persistEncrypted(vaultKeypair.privateKey).catch((err) => {
219→          console.warn('[search] Failed to persist index after rebuild:', err);
220→        });
221→      }, [vaultKeypair]);
222→
223→      // Clear index (called on logout)
224→      const clearIndex = useCallback(async () => {
225→        try {
226→          await searchIndexService.clear();
227→        } catch (err) {
228→          console.warn('[search] Failed to clear index:', err);
229→        }
230→        setIsIndexReady(false);
231→        hasLoadedFromDb.current = false;
232→        setIsOpen(false);
233→        setQuery('');
234→        setResults([]);
235→      }, []);
236→
237→      return {
238→        isOpen,
239→        query,
240→        setQuery,
241→        results,
242→        isIndexReady,
243→        isBuilding,
244→        open,
245→        close,
246→        toggle,
247→        rebuildIndex,
248→        clearIndex,
249→        resultCount: results.length,
250→      };
251→    }
252→    ```
