263→
264→    Component structure:
265→
266→    ```tsx
267→    interface SearchPaletteProps {
268→      isOpen: boolean;
269→      query: string;
270→      onQueryChange: (q: string) => void;
271→      results: SearchResult[];
272→      resultCount: number;
273→      isBuilding: boolean;
274→      isIndexReady: boolean;
275→      onClose: () => void;
276→      onSelectResult: (result: SearchResult) => void;
277→    }
278→
279→    export function SearchPalette({ ... }: SearchPaletteProps) {
280→      const [selectedIndex, setSelectedIndex] = useState(0);
281→      const inputRef = useRef<HTMLInputElement>(null);
282→      const resultsRef = useRef<HTMLDivElement>(null);
283→
284→      // Reset selection when results change
285→      useEffect(() => setSelectedIndex(0), [results]);
286→
287→      // Focus input when opening
288→      useEffect(() => {
289→        if (isOpen) inputRef.current?.focus();
290→      }, [isOpen]);
291→
292→      // Keyboard navigation
293→      const handleKeyDown = (e: React.KeyboardEvent) => {
294→        switch (e.key) {
295→          case 'ArrowDown':
296→            e.preventDefault();
297→            setSelectedIndex((i) => Math.min(i + 1, results.length - 1));
298→            break;
299→          case 'ArrowUp':
300→            e.preventDefault();
301→            setSelectedIndex((i) => Math.max(i - 1, 0));
302→            break;
303→          case 'Enter':
304→            e.preventDefault();
305→            if (results[selectedIndex]) {
306→              onSelectResult(results[selectedIndex]);
307→            }
308→            break;
309→          case 'Escape':
310→            e.preventDefault();
311→            onClose();
312→            break;
313→        }
314→      };
315→
316→      // Scroll selected item into view
317→      useEffect(() => {
318→        const container = resultsRef.current;
319→        if (!container) return;
320→        const selected = container.children[selectedIndex] as HTMLElement | undefined;
321→        selected?.scrollIntoView({ block: 'nearest' });
322→      }, [selectedIndex]);
323→
324→      // Click outside to close
325→      const backdropRef = useRef<HTMLDivElement>(null);
326→      const handleBackdropClick = (e: React.MouseEvent) => {
327→        if (e.target === backdropRef.current) onClose();
328→      };
329→
330→      if (!isOpen) return null;
331→
332→      // File type icon mapping (lucide icon names as Unicode or simple SVG)
333→      // Use simple text-based icons for terminal aesthetic:
334→      // folder -> [D], file -> based on extension
335→      // Actually use lucide-react if available, otherwise CSS-based icons
336→
337→      return (
338→        <div
339→          className="search-backdrop"
340→          ref={backdropRef}
341→          onClick={handleBackdropClick}
342→          role="dialog"
343→          aria-modal="true"
344→          aria-label="Search files"
345→        >
346→          <div className="search-palette" onKeyDown={handleKeyDown}>
347→            {/* Search input */}
348→            <div className="search-input-row">
349→              <span className="search-icon">&#x2315;</span> {/* magnifying glass alternative, or use > prompt */}
350→              <input
351→                ref={inputRef}
352→                className="search-input"
353→                type="text"
354→                placeholder="Search files..."
355→                value={query}
356→                onChange={(e) => onQueryChange(e.target.value)}
357→                autoComplete="off"
358→                spellCheck={false}
359→              />
360→              <span className="search-esc-hint">ESC</span>
361→            </div>
362→
363→            {/* Results area */}
364→            <div className="search-results" ref={resultsRef}>
365→              {isBuilding && (
366→                <div className="search-building">{'// building index...'}</div>
367→              )}
368→              {!isBuilding && isIndexReady && query.trim() && results.length === 0 && (
369→                <div className="search-no-results">
370→                  {'// no results for '}&apos;{query}&apos;
371→                </div>
372→              )}
373→              {results.map((result, index) => (
374→                <SearchResultItem
375→                  key={result.id}
376→                  result={result}
377→                  isSelected={index === selectedIndex}
378→                  onClick={() => onSelectResult(result)}
379→                  onMouseEnter={() => setSelectedIndex(index)}
380→                />
381→              ))}
382→            </div>
383→
384→            {/* Footer with keyboard hints and result count */}
385→            <div className="search-footer">
386→              <span className="search-footer-hints">
387→                <kbd>&uarr;&darr;</kbd> navigate <kbd>&crarr;</kbd> open <kbd>esc</kbd> close
388→              </span>
389→              {results.length > 0 && (
390→                <span className="search-footer-count">
391→                  {'// '}{results.length} result{results.length !== 1 ? 's' : ''}
392→                </span>
393→              )}
394→            </div>
395→          </div>
396→        </div>
397→      );
398→    }
399→    ```
